一个小型的状态机，通过遍历输入的字节序列，根据当前状态（n13）和当前字符决定是否继续或接受。n13 既当索引又当状态，每次循环根据当前字符更新。每次循环重置，仅用于检查当前字符是否映射到特定值。等价于判断当前字符是否为某个固定的 ASCII 码。转移表计算方式`(v3 + 64) % 128`。

##### 解密脚本

```python
from collections import deque

def find_valid_ptrs():
    # 正常状态转移表：state -> {输入字符(ASCII): 下一状态}
    trans = {
        0: {ord("0"): 1},
        1: {ord("9"): 2},
        2: {ord("v"): 3},
        3: {ord("d"): 4},
        4: {ord("f"): 5},
        5: {ord("7"): 6},
        6: {ord("w"): 7},
        7: {ord("e"): 8},
        8: {ord("f"): 9},
        9: {ord("i"): 10},
        10: {ord("j"): 11},
        11: {ord("b"): 12},
        12: {ord("6"): 13},  # 继续转移到状态13
        13: {},  # 状态13无正常转移
        14: {ord("1"): 15, ord("5"): 15},
        15: {ord("4"): 16},
        16: {},
        17: {ord("m"): 18},
        18: {},
        19: {ord("l"): 20},
        20: {ord("2"): 21, ord("r"): 21},
        21: {},
        22: {ord("x"): 23},
        23: {ord("y"): 24},
        24: {},
        25: {ord("s"): 26},
        26: {ord("u"): 27},
        27: {},
        28: {},
        29: {ord("q"): 30},
        30: {ord("p"): 31},
        31: {},
        32: {},
        33: {},
        35: {ord("a"): 36},
        36: {},
        89: {ord("3"): 90},
        90: {},
    }

    # 终止条件：在某个状态读取特定字符即成功 (state -> list of chars)
    terminate = {
        12: [ord("k")],  # case 107
        13: [ord("\n")],  # case 10
    }

    # BFS 搜索所有有效路径
    q = deque()
    q.append((0, []))  # (当前状态, 已读取字节列表)
    visited = set([0])
    results = []

    while q:
        state, path = q.popleft()

        # 1) 检查当前状态是否有终止字符
        if state in terminate:
            for ch in terminate[state]:
                full_path = path + [ch]
                results.append(bytes(full_path))

        # 2) 处理正常转移
        if state in trans:
            for ch, next_state in trans[state].items():
                if next_state not in visited:
                    visited.add(next_state)
                    q.append((next_state, path + [ch]))

    return results

ptrs = find_valid_ptrs()
for p in ptrs:
    # 以字节串和可读字符串形式输出（换行符显示为 \n）
    print(f"repr: {repr(p)}")

